window.READING_REVIEW_DATA={"title":"How they move","items":[{"id":"move-905beb5f5613","term":"consist of","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"由……组成","contextSenses":[0],"legacyId":"consist of|由……组成","note":"常见义：构成某整体；学习用法：系统或物质的组成；be composed of；辨析：注意 consist 不用被动式；consistent 是一致的，不是其动词义","examples":[{"en":"Like a passenger train, a roller coaster consists of a series of connected cars that move on a track.","zh":"像客运列车一样，过山车由一系列相互连接、沿轨道运行的车厢组成。","source":"original","number":1,"paragraph":"A"}],"para":"A","sourceId":"move-A1","paragraph":"A","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-A1","form":"consists of","kind":"variant"},"sourceOrder":10041},{"id":"move-70b5e0c75251","term":"track","type":"word","ipa":"træk","pos":"n. 名词","stars":2,"zh":"轨道","contextSenses":[0],"legacyId":"track|轨道","note":"常见义：轨道；小路；踪迹；学习用法：轨道；发展轨迹；追踪数据；辨析：动词 track 可指追踪，不只是名词跑道","examples":[{"en":"Like a passenger train, a roller coaster consists of a series of connected cars that move on a track.","zh":"像客运列车一样，过山车由一系列相互连接、沿轨道运行的车厢组成。","source":"original","number":1,"paragraph":"A"}],"para":"A","sourceId":"move-A1","paragraph":"A","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-A1","form":"a track","kind":"literal"},"sourceOrder":10093},{"id":"move-62a116a4682b","term":"unlike","type":"word","ipa":"ʌnˈlaɪk","pos":"prep. 介词","stars":3,"zh":"与……不同","contextSenses":[0],"legacyId":"unlike|与……不同","note":"常见义：不像；与……不同；学习用法：对比两种事物；辨析：此处是介词，后接名词；不能直接当连词接完整句","examples":[{"en":"But unlike a passenger train, it has no engine or power source of its own.","zh":"但与客运列车不同，它没有自己的发动机或动力源。","source":"original","number":2,"paragraph":"A"}],"para":"A","sourceId":"move-A2","paragraph":"A","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-A2","form":"unlike","kind":"literal"},"sourceOrder":20004},{"id":"move-26a95b6dfbc0","term":"source","type":"word","ipa":"sɔːs","pos":"n.","stars":2,"zh":"来源，这里是动力源","contextSenses":[0],"legacyId":"source|来源，这里是动力源","note":"常见义：来源；源头；学习用法：energy source 能源；source of information 信息来源；辨析：动词 source 可指采购或寻找供应来源","examples":[{"en":"But unlike a passenger train, it has no engine or power source of its own.","zh":"但与客运列车不同，它没有自己的发动机或动力源。","source":"original","number":2,"paragraph":"A"}],"para":"A","sourceId":"move-A2","paragraph":"A","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-A2","form":"source","kind":"literal"},"sourceOrder":20056},{"id":"move-fd2b4f5ffa72","term":"force","type":"word","ipa":"fɔːs","pos":"n. 名词","stars":2,"zh":"作用力","contextSenses":[0],"legacyId":"force|作用力","note":"常见义：力量；武力；强迫；学习用法：自然力；驱动力；force sb to do 强迫某人做；辨析：forces 在科学语境中指多种力，不是军队","examples":[{"en":"For most of the ride, it is moved only by the forces of inertia and gravity.","zh":"在行程的大部分时间里，它只靠惯性和重力作用而运动。","source":"original","number":3,"paragraph":"A"}],"para":"A","sourceId":"move-A3","paragraph":"A","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-A3","form":"the forces","kind":"variant"},"sourceOrder":30042},{"id":"move-5366a515530b","term":"inertia","type":"word","ipa":"ɪˈnɜːʃə","pos":"n. 名词","stars":5,"zh":"惯性","contextSenses":[0],"legacyId":"inertia|惯性","note":"常见义：惯性；惰性；学习用法：物理惯性；组织缺乏改变的动力；辨析：社会语境可指因循不变；gravity 本句为重力，另可指严重性","examples":[{"en":"For most of the ride, it is moved only by the forces of inertia and gravity.","zh":"在行程的大部分时间里，它只靠惯性和重力作用而运动。","source":"original","number":3,"paragraph":"A"}],"para":"A","memory":{"method":"词族联想","parts":"inertia（惯性）与 inert（不活跃的、惰性的）联记","tip":"没有足够外力，物体会保持原来的运动状态；本篇列车靠惯性继续前进。","family":"inert 惰性的；inertial 惯性的"},"sourceId":"move-A3","paragraph":"A","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-A3","form":"inertia","kind":"literal"},"sourceOrder":30056},{"id":"move-d1fe4e32293b","term":"exertion","type":"word","ipa":"ɪɡˈzɜːʃən","pos":"n. 名词","stars":4,"zh":"能量的施用或投入","contextSenses":[0],"legacyId":"exertion|能量的施用或投入","note":"常见义：费力；用力；努力；学习用法：physical exertion 体力消耗；exert an influence 施加影响；辨析：exertion 不等于运动本身；此处强调输入能量","examples":[{"en":"The only exertion of energy occurs at the very beginning of the ride when the coaster train is pulled up the lift hill.","zh":"唯一的能量投入发生在行程最开始，也就是过山车列车被拉上提升坡的时候。","source":"original","number":4,"paragraph":"A"}],"para":"A","memory":{"method":"动词→名词","parts":"exert（施加、运用）＋-ion","tip":"将力或能量施加于物体的过程。","family":"exert 施加；exert a force 施力"},"sourceId":"move-A4","paragraph":"A","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-A4","form":"exertion","kind":"literal"},"sourceOrder":40009},{"id":"move-3a6de3ad33ed","term":"occur","type":"word","ipa":"əˈkɜː","pos":"v. 动词","stars":4,"zh":"发生","contextSenses":[0],"legacyId":"occur|发生","note":"常见义：发生；出现；学习用法：变化、事件发生；occur to sb 某人想到；辨析：occur to 不是“发生给某人”","examples":[{"en":"The only exertion of energy occurs at the very beginning of the ride when the coaster train is pulled up the lift hill.","zh":"唯一的能量投入发生在行程最开始，也就是过山车列车被拉上提升坡的时候。","source":"original","number":4,"paragraph":"A"}],"para":"A","memory":{"method":"词族联想","parts":"occur（发生）→ occurrence（发生的事情）","tip":"记 occur—occurred—occurrence，过去式和名词中注意双 r。","family":"occurrence 事件；occurred 发生了"},"sourceId":"move-A4","paragraph":"A","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-A4","form":"occurs","kind":"variant"},"sourceOrder":40028},{"id":"move-d38a0f88a090","term":"mechanism","type":"word","ipa":"ˈmekənɪzəm","pos":"n. 名词","stars":4,"zh":"机械装置","contextSenses":[0],"legacyId":"mechanism|机械装置","note":"常见义：机制；装置；学习用法：运作机制；作用机制；辨析：既可指实体机构，也可指抽象运行方式","examples":[{"en":"The traditional lifting mechanism is a long length of chain running up the hill under the track.","zh":"传统的提升装置是一条很长的链条，沿着轨道下方一直延伸到坡顶。","source":"original","number":5,"paragraph":"B"}],"para":"B","memory":{"method":"词族联想","parts":"mechanism 与 mechanical（机械的）同词族","tip":"把机械结构和运作方式联系起来；本文是提升列车的机械装置。","family":"mechanical 机械的；mechanics 力学"},"sourceId":"move-B1","paragraph":"B","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-B1","form":"mechanism","kind":"literal"},"sourceOrder":50024},{"id":"move-e7f7f57300b7","term":"run","type":"word","ipa":"rʌn","pos":"v. 动词","stars":2,"zh":"沿坡向上延伸","contextSenses":[0],"legacyId":"run|沿坡向上延伸","note":"常见义：跑；运行；经营；学习用法：线路延伸；机器运转；开展活动；辨析：a road runs… 指道路延伸，不是道路在跑","examples":[{"en":"The traditional lifting mechanism is a long length of chain running up the hill under the track.","zh":"传统的提升装置是一条很长的链条，沿着轨道下方一直延伸到坡顶。","source":"original","number":5,"paragraph":"B"}],"para":"B","sourceId":"move-B1","paragraph":"B","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-B1","form":"running","kind":"variant"},"sourceOrder":50060},{"id":"move-c4b06eb79fbc","term":"fasten","type":"word","ipa":"ˈfɑːsən","pos":"v. 动词","stars":3,"zh":"固定，系牢","contextSenses":[0],"legacyId":"fasten|固定，系牢","note":"常见义：扣紧；固定；学习用法：连接或固定部件；辨析：fasten seat belts 系安全带；不是加速","examples":[{"en":"The chain is fastened in a loop, which is wound around a gear at the top of the hill and another one at the bottom.","zh":"链条被固定成一个环，绕在坡顶的一个齿轮和坡底的另一个齿轮上。","source":"original","number":6,"paragraph":"B"}],"para":"B","sourceId":"move-B2","paragraph":"B","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-B2","form":"fastened","kind":"variant"},"sourceOrder":60013},{"id":"move-d259fbbb1178","term":"wind","type":"word","ipa":"waɪnd","pos":"v. 动词","stars":3,"zh":"缠绕，原文 wound","contextSenses":[0],"legacyId":"wind|缠绕，原文 wound","note":"常见义：风；缠绕；蜿蜒；学习用法：wind around 缠绕；winding road 曲折道路；辨析：动词 wind 读 /waɪnd/，过去分词 wound 读 /waʊnd/；不同于伤口 wound","examples":[{"en":"The chain is fastened in a loop, which is wound around a gear at the top of the hill and another one at the bottom.","zh":"链条被固定成一个环，绕在坡顶的一个齿轮和坡底的另一个齿轮上。","source":"original","number":6,"paragraph":"B"}],"para":"B","audioTerm":"to wind","sourceId":"move-B2","paragraph":"B","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-B2","form":"wound","kind":"variant"},"sourceOrder":60042},{"id":"move-45f5198f9100","term":"turn","type":"word","ipa":"tɜːn","pos":"v. 动词","stars":2,"zh":"使旋转","contextSenses":[0],"legacyId":"turn|使旋转","note":"常见义：转动；转向；变成；学习用法：机器转动；turn into 变成；辨析：名词 turn 可指轮次或转折","examples":[{"en":"The gear at the bottom of the hill is turned by a motor.","zh":"坡底的齿轮由一台电动机带动旋转。","source":"original","number":7,"paragraph":"B"}],"para":"B","sourceId":"move-B3","paragraph":"B","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-B3","form":"turned","kind":"variant"},"sourceOrder":70038},{"id":"move-69b4bfb0bd4a","term":"motor","type":"word","ipa":"ˈməʊtə","pos":"n. 名词","stars":2,"zh":"电动机","contextSenses":[0],"legacyId":"motor|电动机","note":"常见义：马达；发动机；学习用法：设备的动力装置；辨析：motor skills 中 motor 指运动的，属于另一词性","examples":[{"en":"The gear at the bottom of the hill is turned by a motor.","zh":"坡底的齿轮由一台电动机带动旋转。","source":"original","number":7,"paragraph":"B"}],"para":"B","sourceId":"move-B3","paragraph":"B","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-B3","form":"a motor","kind":"literal"},"sourceOrder":70048},{"id":"move-77ad5931a76f","term":"continually","type":"word","ipa":"kənˈtɪnjuəli","pos":"adv. 副词","stars":4,"zh":"持续地或反复不断地","contextSenses":[0],"legacyId":"continually|持续地或反复不断地","note":"常见义：不断地；频繁地；学习用法：持续发生的过程；辨析：continuous 常强调不中断，continual 也可强调反复；本句由机械语境理解","examples":[{"en":"This turns the chain so that it continually moves up the hill like a long conveyor belt.","zh":"这使链条转动起来，从而像一条长长的传送带一样持续向坡顶移动。","source":"original","number":8,"paragraph":"B"}],"para":"B","memory":{"method":"后缀构词","parts":"continual（反复持续的）＋-ly","tip":"不断地或反复地；不要一律等同于完全没有间断。","family":"continual 反复不断的；continuously 不间断地"},"sourceId":"move-B4","paragraph":"B","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-B4","form":"continually","kind":"literal"},"sourceOrder":80032},{"id":"move-c75fdfe8b659","term":"conveyor belt","type":"phrase","ipa":"","pos":"短语／搭配","stars":2,"zh":"传送带","contextSenses":[0],"legacyId":"conveyor belt|传送带","note":"常见义：输送带；学习用法：工厂或流程图中的输送装置；辨析：belt 单独可指腰带或地理带，如 green belt","examples":[{"en":"This turns the chain so that it continually moves up the hill like a long conveyor belt.","zh":"这使链条转动起来，从而像一条长长的传送带一样持续向坡顶移动。","source":"original","number":8,"paragraph":"B"}],"para":"B","sourceId":"move-B4","paragraph":"B","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-B4","form":"conveyor belt","kind":"literal"},"sourceOrder":80074},{"id":"move-09acfa986d26","term":"grip onto","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"紧紧抓住或扣住","contextSenses":[0],"legacyId":"grip onto|紧紧抓住或扣住","note":"常见义：抓牢；学习用法：grip 抓握；控制；辨析：名词 grip 可指控制力或理解能力；get to grips with 着手处理","examples":[{"en":"The coaster cars grip onto the chain, which simply pulls them to the top.","zh":"过山车的车厢抓住链条，链条就把它们拉到顶部。","source":"original","number":9,"paragraph":"B"}],"para":"B","sourceId":"move-B5","paragraph":"B","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-B5","form":"grip onto","kind":"literal"},"sourceOrder":90017},{"id":"move-8441c1cb8cfa","term":"pull","type":"word","ipa":"pʊl","pos":"v. 动词","stars":2,"zh":"拉动车厢","contextSenses":[0],"legacyId":"pull|拉动车厢","note":"常见义：拉；拖；学习用法：pull up 向上拉；pull out 撤出；辨析：pull 作名词可指吸引力或影响力","examples":[{"en":"The coaster cars grip onto the chain, which simply pulls them to the top.","zh":"过山车的车厢抓住链条，链条就把它们拉到顶部。","source":"original","number":9,"paragraph":"B"}],"para":"B","sourceId":"move-B5","paragraph":"B","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-B5","form":"pulls","kind":"variant"},"sourceOrder":90051},{"id":"move-7f747e635bea","term":"summit","type":"word","ipa":"ˈsʌmɪt","pos":"n. 名词","stars":2,"zh":"最高点或坡顶","contextSenses":[0],"legacyId":"summit|最高点或坡顶","note":"常见义：山顶；峰会；学习用法：山顶；国际峰会；辨析：政治新闻中的 summit 指首脑会议","examples":[{"en":"At the summit, the train is released and starts its descent.","zh":"到达最高点时，列车被释放，开始下降。","source":"original","number":10,"paragraph":"B"}],"para":"B","sourceId":"move-B6","paragraph":"B","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-B6","form":"the summit","kind":"literal"},"sourceOrder":100003},{"id":"move-ca2653408276","term":"release","type":"word","ipa":"rɪˈliːs","pos":"v. 动词","stars":3,"zh":"释放，解除牵引","contextSenses":[0],"legacyId":"release|释放，解除牵引","note":"常见义：释放；公布；发行；学习用法：释放能量；发布报告；辨析：release a report 发布报告，并非把报告放走","examples":[{"en":"At the summit, the train is released and starts its descent.","zh":"到达最高点时，列车被释放，开始下降。","source":"original","number":10,"paragraph":"B"}],"para":"B","sourceId":"move-B6","paragraph":"B","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-B6","form":"released","kind":"variant"},"sourceOrder":100028},{"id":"move-c496a595802a","term":"build up","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"积累，逐步形成","contextSenses":[0],"legacyId":"build up|积累，逐步形成","note":"常见义：建立；增强；积累；学习用法：build up energy/confidence 积累能量或信心；辨析：不一定指建造实体建筑","examples":[{"en":"The purpose of this initial ascent is to build up a sort of reservoir of potential energy, which simply means that as the coaster gets higher in the air, there is a greater distance gravity can pull it down.","zh":"最初这次上升的目的，是积累某种势能储备；简单说，就是过山车升得越高，重力能将它向下拉动的距离就越大。","source":"original","number":11,"paragraph":"C"}],"para":"C","sourceId":"move-C1","paragraph":"C","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-C1","form":"build up","kind":"literal"},"sourceOrder":110041},{"id":"move-3ad11817ea0e","term":"reservoir","type":"word","ipa":"ˈrezəvwɑː","pos":"n. 名词","stars":3,"zh":"储备，储存的能量","contextSenses":[0],"legacyId":"reservoir|储备，储存的能量","note":"常见义：水库；储藏库；学习用法：水资源库；储备来源；辨析：本句比喻为能量储备，不是实际水池","examples":[{"en":"The purpose of this initial ascent is to build up a sort of reservoir of potential energy, which simply means that as the coaster gets higher in the air, there is a greater distance gravity can pull it down.","zh":"最初这次上升的目的，是积累某种势能储备；简单说，就是过山车升得越高，重力能将它向下拉动的距离就越大。","source":"original","number":11,"paragraph":"C"}],"para":"C","sourceId":"move-C1","paragraph":"C","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-C1","form":"reservoir","kind":"literal"},"sourceOrder":110060},{"id":"move-19c643f1b8b2","term":"potential","type":"word","ipa":"pəˈtenʃəl","pos":"adj. 形容词","stars":3,"zh":"潜在的，此处 potential energy 势能","contextSenses":[0],"legacyId":"potential|潜在的，此处 potential energy 势能","note":"常见义：潜在的；潜力；学习用法：潜在影响；开发潜力；势能；辨析：名词 potential 是潜力，不是已经实现的成果","examples":[{"en":"The purpose of this initial ascent is to build up a sort of reservoir of potential energy, which simply means that as the coaster gets higher in the air, there is a greater distance gravity can pull it down.","zh":"最初这次上升的目的，是积累某种势能储备；简单说，就是过山车升得越高，重力能将它向下拉动的距离就越大。","source":"original","number":11,"paragraph":"C"}],"para":"C","sourceId":"move-C1","paragraph":"C","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-C1","form":"potential","kind":"literal"},"sourceOrder":110073},{"id":"move-0cab06904b0c","term":"convert into","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"转化为","contextSenses":[0],"legacyId":"convert into|转化为","note":"常见义：改变形式；转换；学习用法：能源转换；用途转换；辨析：convert 还可指改变信仰，不是本句重点","examples":[{"en":"As the train starts coasting down the hill, this potential energy is converted into kinetic energy (energy of motion), and the train speeds up.","zh":"列车开始沿坡滑下时，这些势能转化为动能，也就是运动的能量，列车随之加速。","source":"original","number":12,"paragraph":"D"}],"para":"D","sourceId":"move-D1","paragraph":"D","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-D1","form":"converted into","kind":"variant"},"sourceOrder":120069},{"id":"move-dd389705aaa9","term":"kinetic energy","type":"phrase","ipa":"","pos":"短语／搭配","stars":2,"zh":"动能","contextSenses":[0],"legacyId":"kinetic energy|动能","note":"常见义：运动所具有的能量；学习用法：能源或科学阅读中的动能；辨析：motion 指运动状态，区别于 emotion 情绪","examples":[{"en":"As the train starts coasting down the hill, this potential energy is converted into kinetic energy (energy of motion), and the train speeds up.","zh":"列车开始沿坡滑下时，这些势能转化为动能，也就是运动的能量，列车随之加速。","source":"original","number":12,"paragraph":"D"}],"para":"D","sourceId":"move-D1","paragraph":"D","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-D1","form":"kinetic energy","kind":"literal"},"sourceOrder":120084},{"id":"move-1315dadc2177","term":"maximum","type":"word","ipa":"ˈmæksɪməm","pos":"n. 名词","stars":2,"zh":"最大值","contextSenses":[0],"legacyId":"maximum|最大值","note":"常见义：最大限度；最大的；学习用法：达到最高水平；maximum capacity 最大容量；辨析：minimum 为最小值，注意反义替换","examples":[{"en":"At the bottom of the hill, this has reached its maximum, and this propels the train up the second hill, again building up the potential-energy level.","zh":"到坡底时，动能达到最大值，推动列车爬上第二个坡，再次提高势能水平。","source":"original","number":13,"paragraph":"D"}],"para":"D","sourceId":"move-D2","paragraph":"D","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-D2","form":"maximum","kind":"literal"},"sourceOrder":130048},{"id":"move-1f55d7ef6ce4","term":"propel","type":"word","ipa":"prəˈpel","pos":"v. 动词","stars":4,"zh":"推动列车前进","contextSenses":[0],"legacyId":"propel|推动列车前进","note":"常见义：推进；驱动；学习用法：推动增长或发展；辨析：可用于抽象语境：propel economic growth 推动经济增长","examples":[{"en":"At the bottom of the hill, this has reached its maximum, and this propels the train up the second hill, again building up the potential-energy level.","zh":"到坡底时，动能达到最大值，推动列车爬上第二个坡，再次提高势能水平。","source":"original","number":13,"paragraph":"D"}],"para":"D","memory":{"method":"词族联想","parts":"propel（推动）→ propulsion（推进）","tip":"联想推进列车的力；注意过去式 propelled 双写 l。","family":"propelled 推动了；propulsion 推进"},"sourceId":"move-D2","paragraph":"D","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-D2","form":"propels","kind":"variant"},"sourceOrder":130066},{"id":"move-c4d9b14e43bf","term":"course","type":"word","ipa":"kɔːs","pos":"n. 名词","stars":2,"zh":"轨道的路线或走向","contextSenses":[0],"legacyId":"course|轨道的路线或走向","note":"常见义：课程；过程；路线；学习用法：河道；进程；路线；辨析：本句不是学校课程；in the course of 在……过程中","examples":[{"en":"In this way, the course of the track is constantly converting energy from kinetic to potential and back again.","zh":"通过这种方式，轨道的路线不断使能量在动能与势能之间来回转换。","source":"original","number":14,"paragraph":"E"}],"para":"E","sourceId":"move-E1","paragraph":"E","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-E1","form":"the course","kind":"literal"},"sourceOrder":140013},{"id":"move-dc251ca53cbc","term":"constantly","type":"word","ipa":"ˈkɒnstəntli","pos":"adv. 副词","stars":3,"zh":"不断地","contextSenses":[0],"legacyId":"constantly|不断地","note":"常见义：持续地；经常地；学习用法：持续变化；不断上升；辨析：不必机械理解为每个瞬间绝无间断","examples":[{"en":"In this way, the course of the track is constantly converting energy from kinetic to potential and back again.","zh":"通过这种方式，轨道的路线不断使能量在动能与势能之间来回转换。","source":"original","number":14,"paragraph":"E"}],"para":"E","sourceId":"move-E1","paragraph":"E","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-E1","form":"constantly","kind":"literal"},"sourceOrder":140040},{"id":"move-203ee892be73","term":"fluctuation","type":"word","ipa":"ˌflʌktʃuˈeɪʃən","pos":"n. 名词","stars":4,"zh":"波动","contextSenses":[0],"legacyId":"fluctuation|波动","note":"常见义：起伏；波动；学习用法：价格或数据的上下变化；辨析：不同于单向 decline 或 increase","examples":[{"en":"This fluctuation in acceleration is what makes roller coasters so much fun.","zh":"这种加速度的波动，正是过山车如此有趣的原因。","source":"original","number":15,"paragraph":"E"}],"para":"E","memory":{"method":"后缀构词","parts":"fluctuate（波动）去 e 后接 -ion","tip":"波浪般上下变化就是波动；本文指速度等状态的变化。","family":"fluctuate 波动；fluctuating 波动的"},"sourceId":"move-E2","paragraph":"E","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-E2","form":"fluctuation","kind":"literal"},"sourceOrder":150005},{"id":"move-9c99baf12302","term":"acceleration","type":"word","ipa":"əkˌseləˈreɪʃən","pos":"n. 名词","stars":3,"zh":"加速度的变化所涉及的加速效应","contextSenses":[0],"legacyId":"acceleration|加速度的变化所涉及的加速效应","note":"常见义：加速；加速度；学习用法：增长加速；运动加速度；辨析：acceleration 不能总译成速度，本句为加速度","examples":[{"en":"This fluctuation in acceleration is what makes roller coasters so much fun.","zh":"这种加速度的波动，正是过山车如此有趣的原因。","source":"original","number":15,"paragraph":"E"}],"para":"E","sourceId":"move-E2","paragraph":"E","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-E2","form":"acceleration","kind":"literal"},"sourceOrder":150020},{"id":"move-80ea7d49b79b","term":"winding","type":"word","ipa":"ˈwaɪndɪŋ","pos":"adj. 形容词","stars":3,"zh":"蜿蜒曲折的","contextSenses":[0],"legacyId":"winding|蜿蜒曲折的","note":"常见义：弯曲的；绕行的；学习用法：winding road/track 曲折道路或轨道；辨析：来自动词 wind，不是 wind 风的形容词","examples":[{"en":"At its most basic level, this is all a roller coaster is – a machine that uses gravity and inertia to send a train along a winding track.","zh":"从最基本的层面看，过山车就是这样一种机器：利用重力和惯性，让列车沿着弯曲的轨道行进。","source":"original","number":16,"paragraph":"E"}],"para":"E","sourceId":"move-E3","paragraph":"E","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-E3","form":"a winding","kind":"literal"},"sourceOrder":160121},{"id":"move-0dd4e9ae475a","term":"send","type":"word","ipa":"send","pos":"v. 动词","stars":2,"zh":"使列车沿轨道运动","contextSenses":[0],"legacyId":"send|使列车沿轨道运动","note":"常见义：发送；派遣；使进入某状态；学习用法：send goods 运输货物；send prices soaring 使价格飙升；辨析：本句为使动用法，不是寄送列车","examples":[{"en":"At its most basic level, this is all a roller coaster is – a machine that uses gravity and inertia to send a train along a winding track.","zh":"从最基本的层面看，过山车就是这样一种机器：利用重力和惯性，让列车沿着弯曲的轨道行进。","source":"original","number":16,"paragraph":"E"}],"para":"E","sourceId":"move-E3","paragraph":"E","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-E3","form":"send","kind":"literal"},"sourceOrder":160102},{"id":"move-383e88f92eb0","term":"fascinating","type":"word","ipa":"ˈfæsɪneɪtɪŋ","pos":"adj. 形容词","stars":3,"zh":"引人入胜的","contextSenses":[0],"legacyId":"fascinating|引人入胜的","note":"常见义：令人着迷的；学习用法：评价经历或历史：a fascinating history；辨析：fascinated 描述人的感受，fascinating 描述事物引起的感受","examples":[{"en":"Roller coasters have a long, fascinating history.","zh":"过山车有一段悠久而引人入胜的历史。","source":"original","number":17,"paragraph":"F"}],"para":"F","sourceId":"move-F1","paragraph":"F","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-F1","form":"fascinating","kind":"literal"},"sourceOrder":170029},{"id":"move-3e84b7deae73","term":"ancestor","type":"word","ipa":"ˈænsestə","pos":"n. 名词","stars":3,"zh":"前身","contextSenses":[0],"legacyId":"ancestor|前身","note":"常见义：祖先；先驱；学习用法：物种祖先；技术前身；辨析：本句为技术的前身，不是人的祖辈","examples":[{"en":"Their direct ancestors were ice slides, popular in Russia in the 16th and 17th centuries.","zh":"它们的直接前身是冰滑道，十六和十七世纪时在俄国很流行。","source":"original","number":18,"paragraph":"F"}],"para":"F","sourceId":"move-F2","paragraph":"F","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-F2","form":"ancestors","kind":"variant"},"sourceOrder":180013},{"id":"move-2e01ce1a10dd","term":"popular","type":"word","ipa":"ˈpɒpjələ","pos":"adj. 形容词","stars":2,"zh":"流行的","contextSenses":[0],"legacyId":"popular|流行的","note":"常见义：受欢迎的；大众的；学习用法：受欢迎的活动或选择；辨析：popular belief 指普遍看法，不一定是受喜爱的看法","examples":[{"en":"Their direct ancestors were ice slides, popular in Russia in the 16th and 17th centuries.","zh":"它们的直接前身是冰滑道，十六和十七世纪时在俄国很流行。","source":"original","number":18,"paragraph":"F"}],"para":"F","sourceId":"move-F2","paragraph":"F","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-F2","form":"popular","kind":"literal"},"sourceOrder":180040},{"id":"move-8f21f4886c7f","term":"steep","type":"word","ipa":"stiːp","pos":"adj. 形容词","stars":2,"zh":"陡峭的","contextSenses":[0],"legacyId":"steep|陡峭的","note":"常见义：陡的；急剧的；学习用法：陡坡；steep rise 急剧上涨；辨析：价格语境 steep 可指昂贵","examples":[{"en":"They consisted of a long, steep, wooden slide covered in ice.","zh":"这些滑道由一条长而陡的木制滑道构成，表面覆盖着冰。","source":"original","number":19,"paragraph":"F"}],"para":"F","sourceId":"move-F3","paragraph":"F","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-F3","form":"steep","kind":"literal"},"sourceOrder":190026},{"id":"move-a93e5d103c46","term":"cover","type":"word","ipa":"ˈkʌvə","pos":"v. 动词","stars":2,"zh":"覆盖","contextSenses":[0],"legacyId":"cover|覆盖","note":"常见义：覆盖；包含；报道；学习用法：cover an area 覆盖面积；cover a topic 涉及话题；辨析：cover costs 指支付或足够抵付费用","examples":[{"en":"They consisted of a long, steep, wooden slide covered in ice.","zh":"这些滑道由一条长而陡的木制滑道构成，表面覆盖着冰。","source":"original","number":19,"paragraph":"F"}],"para":"F","sourceId":"move-F3","paragraph":"F","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-F3","form":"covered","kind":"variant"},"sourceOrder":190046},{"id":"move-c9735f0ac1ba","term":"ladder","type":"word","ipa":"ˈlædə","pos":"n.","stars":2,"zh":"梯子","contextSenses":[0],"legacyId":"ladder|梯子","note":"常见义：梯子；阶梯；学习用法：career ladder 职业晋升阶梯；辨析：抽象 ladder 可指等级或晋升路径","examples":[{"en":"Riders walked up a ladder or set of stairs to the top of the slide, as high as 21 metres up.","zh":"乘客沿着梯子或一段楼梯走到滑道顶端，最高可达离地二十一米。","source":"original","number":20,"paragraph":"F"}],"para":"F","sourceId":"move-F4","paragraph":"F","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-F4","form":"a ladder","kind":"literal"},"sourceOrder":200017},{"id":"move-a9c61fda1022","term":"as high as","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"高达","contextSenses":[0],"legacyId":"as high as|高达","note":"常见义：与……一样高；高达；学习用法：强调高度或数量达到某水平；辨析：这里不是比较两个具体物体的身高","examples":[{"en":"Riders walked up a ladder or set of stairs to the top of the slide, as high as 21 metres up.","zh":"乘客沿着梯子或一段楼梯走到滑道顶端，最高可达离地二十一米。","source":"original","number":20,"paragraph":"F"}],"para":"F","sourceId":"move-F4","paragraph":"F","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-F4","form":"as high as","kind":"literal"},"sourceOrder":200068},{"id":"move-1e70dd3de542","term":"shoot","type":"word","ipa":"ʃuːt","pos":"v. 动词","stars":2,"zh":"快速冲下，原文 shot","contextSenses":[0],"legacyId":"shoot|快速冲下，原文 shot","note":"常见义：射击；拍摄；迅速移动；学习用法：shoot up 猛增；shoot down 快速向下移动；辨析：本句不是开枪；shot 是 shoot 的过去式","examples":[{"en":"At the top, they climbed into sleds made of wood or blocks of ice and shot down the slope.","zh":"在顶端，他们坐进用木头或冰块做的雪橇，然后沿坡飞快地滑下。","source":"original","number":21,"paragraph":"F"}],"para":"F","sourceId":"move-F5","paragraph":"F","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-F5","form":"shot","kind":"variant"},"sourceOrder":210070},{"id":"move-c9ccef387846","term":"slope","type":"word","ipa":"sləʊp","pos":"n. 名词","stars":2,"zh":"斜坡","contextSenses":[0],"legacyId":"slope|斜坡","note":"常见义：坡度；斜面；学习用法：地形坡面；图表斜率；辨析：可指线条或曲线的斜率","examples":[{"en":"At the top, they climbed into sleds made of wood or blocks of ice and shot down the slope.","zh":"在顶端，他们坐进用木头或冰块做的雪橇，然后沿坡飞快地滑下。","source":"original","number":21,"paragraph":"F"}],"para":"F","sourceId":"move-F5","paragraph":"F","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-F5","form":"the slope","kind":"literal"},"sourceOrder":210080},{"id":"move-f6976e56e7e4","term":"base","type":"word","ipa":"beɪs","pos":"n. 名词","stars":2,"zh":"底部","contextSenses":[0],"legacyId":"base|底部","note":"常见义：底座；基础；基地；学习用法：at the base 在底部；be based on 基于；辨析：本句不是军事基地","examples":[{"en":"At the base, the sleds would crash-land in a sand pile.","zh":"到达底部时，雪橇会猛地落入一堆沙子中。","source":"original","number":22,"paragraph":"F"}],"para":"F","sourceId":"move-F6","paragraph":"F","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-F6","form":"the base","kind":"literal"},"sourceOrder":220003},{"id":"move-6464d99ef24b","term":"crash-land","type":"word","ipa":"ˈkræʃ lænd","pos":"v. 动词","stars":3,"zh":"猛烈着地","contextSenses":[0],"legacyId":"crash-land|猛烈着地","note":"常见义：迫降；摔落着陆；学习用法：意外着地或迫降；辨析：复合动词，不能仅凭 crash 译成交通碰撞","examples":[{"en":"At the base, the sleds would crash-land in a sand pile.","zh":"到达底部时，雪橇会猛地落入一堆沙子中。","source":"original","number":22,"paragraph":"F"}],"para":"F","sourceId":"move-F6","paragraph":"F","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-F6","form":"crash-land","kind":"literal"},"sourceOrder":220029},{"id":"move-34dedb6463d3","term":"import","type":"word","ipa":"ɪmˈpɔːt","pos":"v.（本文为 imported 的词源动词）","stars":2,"zh":"引进，传入","contextSenses":[0],"legacyId":"import|引进，传入","note":"常见义：进口；引入；学习用法：引进技术或理念；辨析：可用于 idea，不只指进口商品","examples":[{"en":"It seems that the idea was then imported into France.","zh":"这一构想似乎随后传入了法国。","source":"original","number":23,"paragraph":"G"}],"para":"G","sourceId":"move-G1","paragraph":"G","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-G1","form":"imported","kind":"variant"},"sourceOrder":230032},{"id":"move-bce365a41bc8","term":"seem","type":"word","ipa":"siːm","pos":"v. 动词","stars":2,"zh":"似乎","contextSenses":[0],"legacyId":"seem|似乎","note":"常见义：看起来；似乎；学习用法：It seems that… 谨慎表达判断；辨析：标记推测，不等于作者明确确证","examples":[{"en":"It seems that the idea was then imported into France.","zh":"这一构想似乎随后传入了法国。","source":"original","number":23,"paragraph":"G"}],"para":"G","sourceId":"move-G1","paragraph":"G","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-G1","form":"seems","kind":"variant"},"sourceOrder":230003},{"id":"move-c7cc6d454bdf","term":"melt","type":"word","ipa":"melt","pos":"v. 动词","stars":2,"zh":"融化","contextSenses":[0],"legacyId":"melt|融化","note":"常见义：融化；熔化；学习用法：冰川消融；材料熔化；辨析：melt away 可比喻逐渐消失","examples":[{"en":"For most of the year, the warmer climate would melt the ice, so the French started building waxed slides instead.","zh":"一年中的大部分时间，较暖的气候会让冰融化，因此法国人转而建造涂蜡的滑道。","source":"original","number":24,"paragraph":"G"}],"para":"G","sourceId":"move-G2","paragraph":"G","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-G2","form":"melt","kind":"literal"},"sourceOrder":240047},{"id":"move-da260aadf699","term":"instead","type":"word","ipa":"ɪnˈsted","pos":"adv. 副词","stars":2,"zh":"改用另一种方式","contextSenses":[0],"legacyId":"instead|改用另一种方式","note":"常见义：代替；反而；学习用法：替代方案；instead of 替代……；辨析：instead 为副词，instead of 后接名词或动名词","examples":[{"en":"For most of the year, the warmer climate would melt the ice, so the French started building waxed slides instead.","zh":"一年中的大部分时间，较暖的气候会让冰融化，因此法国人转而建造涂蜡的滑道。","source":"original","number":24,"paragraph":"G"}],"para":"G","sourceId":"move-G2","paragraph":"G","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-G2","form":"instead","kind":"literal"},"sourceOrder":240105},{"id":"move-71ad19139ab0","term":"attach to","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"连接到","contextSenses":[0],"legacyId":"attach to|连接到","note":"常见义：附上；固定到；学习用法：将部件连接到装置；attach importance to 重视；辨析：attach importance to 中不是物理连接","examples":[{"en":"To help the sleds move down these slides, they added wheels, and in 1817, for the first time, a train was attached to the track.","zh":"为了帮助雪橇沿这些滑道滑下，他们给雪橇加上车轮；到一八一七年，列车首次被连接到轨道上。","source":"original","number":25,"paragraph":"G"}],"para":"G","sourceId":"move-G3","paragraph":"G","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-G3","form":"attached to","kind":"variant"},"sourceOrder":250106},{"id":"move-ac7c6318337d","term":"for the first time","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"首次","contextSenses":[0],"legacyId":"for the first time|首次","note":"常见义：第一次；学习用法：历史事件的首次出现；辨析：first 不意味着之后没有再发生","examples":[{"en":"To help the sleds move down these slides, they added wheels, and in 1817, for the first time, a train was attached to the track.","zh":"为了帮助雪橇沿这些滑道滑下，他们给雪橇加上车轮；到一八一七年，列车首次被连接到轨道上。","source":"original","number":25,"paragraph":"G"}],"para":"G","sourceId":"move-G3","paragraph":"G","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-G3","form":"for the first time","kind":"literal"},"sourceOrder":250074},{"id":"move-f8eaa7a6cf2d","term":"expand on","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"进一步发展或展开","contextSenses":[0],"legacyId":"expand on|进一步发展或展开","note":"常见义：详细阐述；扩展；学习用法：expand on an idea 进一步说明想法；辨析：这里不只是扩大实体尺寸","examples":[{"en":"The French continued to expand on this idea, coming up with more complex track layouts, with multiple cars and all sorts of twists and turns.","zh":"法国人继续发展这一构想，设计出更复杂的轨道布局，包括多节车厢和各种弯道转折。","source":"original","number":26,"paragraph":"G"}],"para":"G","sourceId":"move-G4","paragraph":"G","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-G4","form":"expand on","kind":"literal"},"sourceOrder":260024},{"id":"move-fd18d0447989","term":"come up with","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"想出，设计出","contextSenses":[0],"legacyId":"come up with|想出，设计出","note":"常见义：提出；想出；学习用法：提出方案或解释；辨析：不是“和……一起上来”","examples":[{"en":"The French continued to expand on this idea, coming up with more complex track layouts, with multiple cars and all sorts of twists and turns.","zh":"法国人继续发展这一构想，设计出更复杂的轨道布局，包括多节车厢和各种弯道转折。","source":"original","number":26,"paragraph":"G"}],"para":"G","sourceId":"move-G4","paragraph":"G","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-G4","form":"coming up with","kind":"variant"},"sourceOrder":260045},{"id":"move-3d68323680ca","term":"layout","type":"word","ipa":"ˈleɪaʊt","pos":"n. 名词","stars":3,"zh":"布局","contextSenses":[0],"legacyId":"layout|布局","note":"常见义：安排；版面；布局；学习用法：建筑或设备布局；辨析：layout 不等于 outline 大纲","examples":[{"en":"The French continued to expand on this idea, coming up with more complex track layouts, with multiple cars and all sorts of twists and turns.","zh":"法国人继续发展这一构想，设计出更复杂的轨道布局，包括多节车厢和各种弯道转折。","source":"original","number":26,"paragraph":"G"}],"para":"G","sourceId":"move-G4","paragraph":"G","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-G4","form":"layouts","kind":"variant"},"sourceOrder":260079},{"id":"move-b5cae87b008a","term":"originally","type":"word","ipa":"əˈrɪdʒənəli","pos":"adv. 副词","stars":3,"zh":"最初","contextSenses":[0],"legacyId":"originally|最初","note":"常见义：原来；起初；学习用法：原始用途与后来用途对照；辨析：不等于 originally“原创地”；original 可指原始的","examples":[{"en":"The first American roller coaster was built in the mountains of Pennsylvania in the mid-1800s, originally to provide an easy way to send coal to the railway 29 km down the mountain.","zh":"美国第一座过山车于十九世纪中叶建在宾夕法尼亚州山区，最初是为了方便把煤送到山下二十九公里处的铁路。","source":"original","number":27,"paragraph":"H"}],"para":"H","sourceId":"move-H1","paragraph":"H","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-H1","form":"originally","kind":"literal"},"sourceOrder":270095},{"id":"move-7278e0b7ab5d","term":"provide","type":"word","ipa":"prəˈvaɪd","pos":"v. 动词","stars":2,"zh":"提供","contextSenses":[0],"legacyId":"provide|提供","note":"常见义：供给；提供；学习用法：provide a way to do 提供某种方法；辨析：provide sb with sth 与 provide sth for sb 结构不同","examples":[{"en":"The first American roller coaster was built in the mountains of Pennsylvania in the mid-1800s, originally to provide an easy way to send coal to the railway 29 km down the mountain.","zh":"美国第一座过山车于十九世纪中叶建在宾夕法尼亚州山区，最初是为了方便把煤送到山下二十九公里处的铁路。","source":"original","number":27,"paragraph":"H"}],"para":"H","sourceId":"move-H1","paragraph":"H","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-H1","form":"provide","kind":"literal"},"sourceOrder":270109},{"id":"move-8d6be43903d5","term":"crew","type":"word","ipa":"kruː","pos":"n. 名词","stars":2,"zh":"工作人员，作业班组","contextSenses":[0],"legacyId":"crew|工作人员，作业班组","note":"常见义：全体船员；机组；工作人员；学习用法：执行同一任务的团队；辨析：不只指船员；本句为运煤作业人员","examples":[{"en":"When the track was first built, a crew at the bottom of the mountain would attach the cart to a team of mules after emptying the load, and the mules would drag it back up to the top.","zh":"轨道刚建成时，山脚的工作人员会在卸空载荷后，把车连接到一队骡子上，由骡子把车拉回山顶。","source":"original","number":28,"paragraph":"H"}],"para":"H","sourceId":"move-H2","paragraph":"H","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-H2","form":"a crew","kind":"literal"},"sourceOrder":280032},{"id":"move-4ccbf09ffe51","term":"load","type":"word","ipa":"ləʊd","pos":"v. 动词","stars":2,"zh":"载荷，所装的煤","contextSenses":[0],"legacyId":"load|载荷，所装的煤","note":"常见义：负载；装载量；装载；学习用法：工作负担；货物载荷；辨析：a heavy workload 很重的工作量","examples":[{"en":"When the track was first built, a crew at the bottom of the mountain would attach the cart to a team of mules after emptying the load, and the mules would drag it back up to the top.","zh":"轨道刚建成时，山脚的工作人员会在卸空载荷后，把车连接到一队骡子上，由骡子把车拉回山顶。","source":"original","number":28,"paragraph":"H"}],"para":"H","sourceId":"move-H2","paragraph":"H","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-H2","form":"the load","kind":"literal"},"sourceOrder":280125},{"id":"move-c88ed1bc3b7e","term":"replace with","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"用……取代","contextSenses":[0],"legacyId":"replace with|用……取代","note":"常见义：替换；学习用法：A is replaced with B＝B 取代 A；辨析：替换方向易错，不能颠倒","examples":[{"en":"They were eventually replaced with steam engines to make the system more efficient.","zh":"后来，骡子最终被蒸汽机取代，使系统更加高效。","source":"original","number":29,"paragraph":"H"}],"para":"H","sourceId":"move-H3","paragraph":"H","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-H3","form":"replaced with","kind":"variant"},"sourceOrder":290021},{"id":"move-893b3bb5d09c","term":"efficient","type":"word","ipa":"ɪˈfɪʃənt","pos":"adj. 形容词","stars":4,"zh":"高效的","contextSenses":[0],"legacyId":"efficient|高效的","note":"常见义：有效率的；学习用法：能源效率；时间或资源利用效率；辨析：区别 effective 有效果的；高效强调投入与产出","examples":[{"en":"They were eventually replaced with steam engines to make the system more efficient.","zh":"后来，骡子最终被蒸汽机取代，使系统更加高效。","source":"original","number":29,"paragraph":"H"}],"para":"H","memory":{"method":"词族联想","parts":"efficient（高效的）→ efficiency（效率）","tip":"用更少投入完成任务是高效，区别 effective（有效的）。","family":"efficiency 效率；inefficient 低效的"},"sourceId":"move-H3","paragraph":"H","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-H3","form":"efficient","kind":"literal"},"sourceOrder":290073},{"id":"move-ef047bb80120","term":"freight","type":"word","ipa":"freɪt","pos":"n. 名词","stars":3,"zh":"货运，货物","contextSenses":[0],"legacyId":"freight|货运，货物","note":"常见义：货物；运输货物；学习用法：freight transport 货物运输；辨析：不等于旅客 passenger","examples":[{"en":"Soon after these improvements were made, the railway company built a new tunnel that brought the freight trains much closer to the coal mine.","zh":"这些改进完成后不久，铁路公司建了一条新隧道，使货运列车能到达离煤矿近得多的地方。","source":"original","number":30,"paragraph":"I"}],"para":"I","sourceId":"move-I1","paragraph":"I","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-I1","form":"the freight","kind":"literal"},"sourceOrder":300093},{"id":"move-6dee793ddf9d","term":"tunnel","type":"word","ipa":"ˈtʌnəl","pos":"n. 名词","stars":2,"zh":"隧道","contextSenses":[0],"legacyId":"tunnel|隧道","note":"常见义：隧道；地道；学习用法：交通基础设施；辨析：tunnel vision 比喻眼光狭窄，非本句义","examples":[{"en":"Soon after these improvements were made, the railway company built a new tunnel that brought the freight trains much closer to the coal mine.","zh":"这些改进完成后不久，铁路公司建了一条新隧道，使货运列车能到达离煤矿近得多的地方。","source":"original","number":30,"paragraph":"I"}],"para":"I","sourceId":"move-I1","paragraph":"I","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-I1","form":"tunnel","kind":"literal"},"sourceOrder":300073},{"id":"move-be9e3de4be78","term":"configure","type":"word","ipa":"kənˈfɪɡə","pos":"v. 动词","stars":3,"zh":"配置，改设","contextSenses":[0],"legacyId":"configure|配置，改设","note":"常见义：设置；配置；学习用法：配置系统或设备；辨析：不是 manufacture 制造","examples":[{"en":"No longer required for its original purpose, the roller coaster was configured as a ‘scenic tour’.","zh":"由于原来的用途已不再需要，过山车被改设成一项观光游览。","source":"original","number":31,"paragraph":"I"}],"para":"I","sourceId":"move-I2","paragraph":"I","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-I2","form":"configured","kind":"variant"},"sourceOrder":310068},{"id":"move-c49e010b281a","term":"scenic","type":"word","ipa":"ˈsiːnɪk","pos":"adj. 形容词","stars":3,"zh":"供观赏风景的","contextSenses":[0],"legacyId":"scenic|供观赏风景的","note":"常见义：风景优美的；学习用法：scenic route 风景路线；辨析：scenery 是不可数名词“风景”","examples":[{"en":"No longer required for its original purpose, the roller coaster was configured as a ‘scenic tour’.","zh":"由于原来的用途已不再需要，过山车被改设成一项观光游览。","source":"original","number":31,"paragraph":"I"}],"para":"I","sourceId":"move-I2","paragraph":"I","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-I2","form":"a ‘scenic","kind":"literal"},"sourceOrder":310082},{"id":"move-fe3b1deeab1e","term":"leisurely","type":"word","ipa":"ˈleʒəli","pos":"adj. 形容词","stars":3,"zh":"悠闲从容的","contextSenses":[0],"legacyId":"leisurely|悠闲从容的","note":"常见义：不慌不忙的；学习用法：a leisurely walk/ride 悠闲散步或乘行；辨析：leisure 为闲暇；leisurely 可作形容词或副词","examples":[{"en":"For one dollar, tourists got a leisurely ride up to the top of the mountain, followed by a wild, bumpy ride straight down.","zh":"游客花一美元，便可先悠闲地乘车上山，然后一路猛冲而下，体验颠簸刺激的旅程。","source":"original","number":32,"paragraph":"I"}],"para":"I","sourceId":"move-I3","paragraph":"I","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-I3","form":"a leisurely","kind":"literal"},"sourceOrder":320029},{"id":"move-b038aad6ec96","term":"bumpy","type":"word","ipa":"ˈbʌmpi","pos":"adj. 形容词","stars":3,"zh":"颠簸的","contextSenses":[0],"legacyId":"bumpy|颠簸的","note":"常见义：坑洼的；不平稳的；学习用法：道路颠簸；bumpy ride 艰难经历；辨析：可比喻一段困难的过程","examples":[{"en":"For one dollar, tourists got a leisurely ride up to the top of the mountain, followed by a wild, bumpy ride straight down.","zh":"游客花一美元，便可先悠闲地乘车上山，然后一路猛冲而下，体验颠簸刺激的旅程。","source":"original","number":32,"paragraph":"I"}],"para":"I","sourceId":"move-I3","paragraph":"I","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-I3","form":"bumpy","kind":"literal"},"sourceOrder":320097},{"id":"move-d52fc3b28376","term":"resounding","type":"word","ipa":"rɪˈzaʊndɪŋ","pos":"adj. 形容词","stars":3,"zh":"显著而彻底的","contextSenses":[0],"legacyId":"resounding|显著而彻底的","note":"常见义：响亮的；巨大的；学习用法：a resounding success 大获成功；辨析：不能直译为成功在发出响声","examples":[{"en":"This was soon a resounding success, attracting thousands of tourists every year.","zh":"这一项目很快大获成功，每年吸引数千名游客。","source":"original","number":33,"paragraph":"I"}],"para":"I","sourceId":"move-I4","paragraph":"I","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-I4","form":"a resounding","kind":"literal"},"sourceOrder":330014},{"id":"move-4df30e7f611f","term":"attract","type":"word","ipa":"əˈtrækt","pos":"v. 动词","stars":2,"zh":"吸引","contextSenses":[0],"legacyId":"attract|吸引","note":"常见义：引起兴趣；吸引；学习用法：吸引游客或投资；辨析：attract attention 引起注意","examples":[{"en":"This was soon a resounding success, attracting thousands of tourists every year.","zh":"这一项目很快大获成功，每年吸引数千名游客。","source":"original","number":33,"paragraph":"I"}],"para":"I","sourceId":"move-I4","paragraph":"I","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-I4","form":"attracting","kind":"variant"},"sourceOrder":330036},{"id":"move-07c6183ed60b","term":"thrive","type":"word","ipa":"θraɪv","pos":"v. 动词","stars":3,"zh":"兴盛，蓬勃发展","contextSenses":[0],"legacyId":"thrive|兴盛，蓬勃发展","note":"常见义：茁壮成长；繁荣；学习用法：企业发展；物种繁衍；辨析：不仅是勉强 survive，而是状态良好","examples":[{"en":"Scenic rides like this continued to thrive and were joined by wooden roller coasters similar to the ones we know today.","zh":"类似的观光乘行项目继续蓬勃发展，并出现了与今天我们熟悉的过山车相似的木制过山车。","source":"original","number":34,"paragraph":"J"}],"para":"J","sourceId":"move-J1","paragraph":"J","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-J1","form":"thrive","kind":"literal"},"sourceOrder":340036},{"id":"move-aa1ee5b18124","term":"join","type":"word","ipa":"dʒɔɪn","pos":"v. 动词","stars":2,"zh":"加入同一发展潮流","contextSenses":[0],"legacyId":"join|加入同一发展潮流","note":"常见义：参加；连接；加入；学习用法：加入组织；连接部件；辨析：were joined by 意为另一些项目也出现了，并非连接车厢","examples":[{"en":"Scenic rides like this continued to thrive and were joined by wooden roller coasters similar to the ones we know today.","zh":"类似的观光乘行项目继续蓬勃发展，并出现了与今天我们熟悉的过山车相似的木制过山车。","source":"original","number":34,"paragraph":"J"}],"para":"J","sourceId":"move-J1","paragraph":"J","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-J1","form":"joined","kind":"variant"},"sourceOrder":340052},{"id":"move-ac37c92b4a97","term":"attraction","type":"word","ipa":"əˈtrækʃən","pos":"n. 名词","stars":3,"zh":"吸引游客的项目","contextSenses":[0],"legacyId":"attraction|吸引游客的项目","note":"常见义：吸引力；景点；学习用法：tourist attraction 旅游景点；辨析：可数 an attraction 指具体项目，不是抽象吸引力","examples":[{"en":"These coasters were the main attraction at popular amusement parks throughout the United States, such as the many parks of Coney Island in New York.","zh":"这些过山车成为美国各地热门游乐园的主要吸引项目，例如纽约康尼岛的众多游乐园。","source":"original","number":35,"paragraph":"J"}],"para":"J","sourceId":"move-J2","paragraph":"J","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-J2","form":"attraction","kind":"literal"},"sourceOrder":350029},{"id":"move-eb85303e8ef9","term":"throughout","type":"word","ipa":"θruːˈaʊt","pos":"prep. 介词","stars":3,"zh":"遍及美国","contextSenses":[0],"legacyId":"throughout|遍及美国","note":"常见义：遍及；贯穿；学习用法：空间全范围；整个期间；辨析：throughout the year 表全年，不是穿过一年","examples":[{"en":"These coasters were the main attraction at popular amusement parks throughout the United States, such as the many parks of Coney Island in New York.","zh":"这些过山车成为美国各地热门游乐园的主要吸引项目，例如纽约康尼岛的众多游乐园。","source":"original","number":35,"paragraph":"J"}],"para":"J","sourceId":"move-J2","paragraph":"J","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-J2","form":"throughout","kind":"literal"},"sourceOrder":350067},{"id":"move-95e044036a29","term":"in full swing","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"正盛行，处于活跃阶段","contextSenses":[0],"legacyId":"in full swing|正盛行，处于活跃阶段","note":"常见义：全面展开；正热烈进行；学习用法：活动或产业全面开展；辨析：不是指秋千在摆动","examples":[{"en":"By the 1920s, roller coasters were in full swing, with some 2,000 rides in operation around the country.","zh":"到二十世纪二十年代，过山车已进入全盛时期，全国约有两千个项目在运营。","source":"original","number":36,"paragraph":"J"}],"para":"J","sourceId":"move-J3","paragraph":"J","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-J3","form":"in full swing","kind":"literal"},"sourceOrder":360035},{"id":"move-6e61c172319c","term":"some","type":"word","ipa":"sʌm","pos":"det. 限定词","stars":1,"zh":"大约两千中的大约","contextSenses":[0],"legacyId":"some|大约两千中的大约","note":"常见义：一些；某个；大约；学习用法：some + 数字 可作估算；辨析：本句不是“两千中的一些”","examples":[{"en":"By the 1920s, roller coasters were in full swing, with some 2,000 rides in operation around the country.","zh":"到二十世纪二十年代，过山车已进入全盛时期，全国约有两千个项目在运营。","source":"original","number":36,"paragraph":"J"}],"para":"J","sourceId":"move-J3","paragraph":"J","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-J3","form":"some","kind":"literal"},"sourceOrder":360055},{"id":"move-69a79285e7f8","term":"in operation","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"正在运营","contextSenses":[0],"legacyId":"in operation|正在运营","note":"常见义：在运行或使用中；学习用法：设施、制度投入运作；辨析：operation 可指手术、经营或操作","examples":[{"en":"By the 1920s, roller coasters were in full swing, with some 2,000 rides in operation around the country.","zh":"到二十世纪二十年代，过山车已进入全盛时期，全国约有两千个项目在运营。","source":"original","number":36,"paragraph":"J"}],"para":"J","sourceId":"move-J3","paragraph":"J","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-J3","form":"in operation","kind":"literal"},"sourceOrder":360072},{"id":"move-e46cc8e84184","term":"boom","type":"word","ipa":"buːm","pos":"n./v.","stars":2,"zh":"繁荣，快速发展期","contextSenses":[0],"legacyId":"boom|繁荣，快速发展期","note":"常见义：繁荣；激增；轰鸣；学习用法：economic boom 经济繁荣；辨析：不是所有 boom 都表示爆炸声","examples":[{"en":"Following the Great Depression, a decline in roller-coaster production began in the early 1930s, but a second roller-coaster boom in the 1970s and the beginning of the 1980s revitalised the amusement-park industry and introduced a slew of innovative tubular steel coasters.","zh":"大萧条之后，过山车生产从二十世纪三十年代初开始下滑；但七十年代及八十年代初的第二次繁荣，重振了游乐园行业，并带来了一大批创新的钢管过山车。","source":"original","number":37,"paragraph":"K"}],"para":"K","sourceId":"move-K1","paragraph":"K","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-K1","form":"boom","kind":"literal"},"sourceOrder":370125},{"id":"move-567600f5ae92","term":"revitalise","type":"word","ipa":"ˌriːˈvaɪtəlaɪz","pos":"v. 动词","stars":4,"zh":"使重新焕发生机","contextSenses":[0],"legacyId":"revitalise|使重新焕发生机","note":"常见义：重振；振兴；学习用法：revitalise an industry 重振行业；辨析：re- 表再次，与 vital 的生命力概念相连","examples":[{"en":"Following the Great Depression, a decline in roller-coaster production began in the early 1930s, but a second roller-coaster boom in the 1970s and the beginning of the 1980s revitalised the amusement-park industry and introduced a slew of innovative tubular steel coasters.","zh":"大萧条之后，过山车生产从二十世纪三十年代初开始下滑；但七十年代及八十年代初的第二次繁荣，重振了游乐园行业，并带来了一大批创新的钢管过山车。","source":"original","number":37,"paragraph":"K"}],"para":"K","memory":{"method":"前缀＋词族","parts":"re-（重新）＋vitalise（使有活力）","tip":"让已经衰落的事物重新焕发生机。","family":"vital 有活力的；revitalisation 振兴"},"acceptedSpellings":["revitalise","revitalize"],"sourceId":"move-K1","paragraph":"K","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-K1","form":"revitalised","kind":"variant"},"sourceOrder":370174},{"id":"move-dd000c20d2ad","term":"a slew of","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"一大批","contextSenses":[0],"legacyId":"a slew of|一大批","note":"常见义：大量，许多；学习用法：a wide range of 更适合稳妥正式写作；辨析：固定搭配 slew of，不是 slow","examples":[{"en":"Following the Great Depression, a decline in roller-coaster production began in the early 1930s, but a second roller-coaster boom in the 1970s and the beginning of the 1980s revitalised the amusement-park industry and introduced a slew of innovative tubular steel coasters.","zh":"大萧条之后，过山车生产从二十世纪三十年代初开始下滑；但七十年代及八十年代初的第二次繁荣，重振了游乐园行业，并带来了一大批创新的钢管过山车。","source":"original","number":37,"paragraph":"K"}],"para":"K","sourceId":"move-K1","paragraph":"K","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-K1","form":"a slew of","kind":"literal"},"sourceOrder":370229},{"id":"move-243def788e8a","term":"of sorts","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"某种程度上的，不完全典型的","contextSenses":[0],"legacyId":"of sorts|某种程度上的，不完全典型的","note":"常见义：勉强算是；某种形式的；学习用法：读出限定，避免把判断绝对化；辨析：不是“各种各样”；all sorts of 才是各种各样","examples":[{"en":"This was followed by a decline in interest for the rest of the decade, but since the early 1990s the amusement-park industry has experienced another coaster boom of sorts.","zh":"此后，这个十年余下的时期里，人们的兴趣下降了；但自二十世纪九十年代初以来，游乐园行业又经历了一轮某种程度上的过山车热潮。","source":"original","number":38,"paragraph":"L"}],"para":"L","sourceId":"move-L1","paragraph":"L","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-L1","form":"of sorts","kind":"literal"},"sourceOrder":380162},{"id":"move-61af983a0d0c","term":"experience","type":"word","ipa":"ɪkˈspɪəriəns","pos":"v. 动词","stars":2,"zh":"经历","contextSenses":[0],"legacyId":"experience|经历","note":"常见义：经历；经验；体验；学习用法：经历增长或衰退；辨析：动词可接变化事件，不只指体验活动","examples":[{"en":"This was followed by a decline in interest for the rest of the decade, but since the early 1990s the amusement-park industry has experienced another coaster boom of sorts.","zh":"此后，这个十年余下的时期里，人们的兴趣下降了；但自二十世纪九十年代初以来，游乐园行业又经历了一轮某种程度上的过山车热潮。","source":"original","number":38,"paragraph":"L"}],"para":"L","sourceId":"move-L1","paragraph":"L","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-L1","form":"experienced","kind":"variant"},"sourceOrder":380129},{"id":"move-916242cddd8f","term":"open up","type":"phrase","ipa":"","pos":"短语／搭配","stars":4,"zh":"开辟，创造更多选择","contextSenses":[0],"legacyId":"open up|开辟，创造更多选择","note":"常见义：打开；开放；开拓；学习用法：open up opportunities 开拓机会；辨析：不是一定要打开实体物品","examples":[{"en":"New launching techniques and other technological developments have opened up a world of options for designers, so in some rides you feel as if you are flying.","zh":"新的发射技术和其他技术发展为设计师带来了丰富的选择，因此在某些项目中，你会感觉仿佛在飞翔。","source":"original","number":39,"paragraph":"L"}],"para":"L","sourceId":"move-L2","paragraph":"L","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-L2","form":"opened up","kind":"variant"},"sourceOrder":390067},{"id":"move-6237cef5163e","term":"as if","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"仿佛，好像","contextSenses":[0],"legacyId":"as if|仿佛，好像","note":"常见义：似乎如同；学习用法：描述感受或假设；辨析：本句 are flying 不代表真的飞行，as if 已标记类比","examples":[{"en":"New launching techniques and other technological developments have opened up a world of options for designers, so in some rides you feel as if you are flying.","zh":"新的发射技术和其他技术发展为设计师带来了丰富的选择，因此在某些项目中，你会感觉仿佛在飞翔。","source":"original","number":39,"paragraph":"L"}],"para":"L","sourceId":"move-L2","paragraph":"L","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-L2","form":"as if","kind":"literal"},"sourceOrder":390137},{"id":"move-e4bbb4b893f8","term":"pop up","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"突然或陆续出现","contextSenses":[0],"legacyId":"pop up|突然或陆续出现","note":"常见义：冒出；出现；学习用法：新店、问题或机会出现；辨析：正式写作中可改 emerge；口语 pop up 很自然","examples":[{"en":"In the next few years we can expect to see many faster, taller and more twisted rides popping up in amusement parks around the world.","zh":"未来几年，我们可以预期在世界各地的游乐园里，出现许多更快、更高、弯曲程度更大的过山车。","source":"original","number":40,"paragraph":"L"}],"para":"L","sourceId":"move-L3","paragraph":"L","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-L3","form":"popping up","kind":"variant"},"sourceOrder":400086},{"id":"move-70ae436de39f","term":"expect to","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"预期会","contextSenses":[0],"legacyId":"expect to|预期会","note":"常见义：期望；预计；学习用法：预计未来发展；辨析：expect 不等于保证必然发生","examples":[{"en":"In the next few years we can expect to see many faster, taller and more twisted rides popping up in amusement parks around the world.","zh":"未来几年，我们可以预期在世界各地的游乐园里，出现许多更快、更高、弯曲程度更大的过山车。","source":"original","number":40,"paragraph":"L"}],"para":"L","sourceId":"move-L3","paragraph":"L","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-L3","form":"expect to","kind":"literal"},"sourceOrder":400029},{"id":"move-37a988cd9b23","term":"a resounding success","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"大获成功","contextSenses":[0],"note":"评价取得显著成功的活动，避免没有依据的夸张。 由原句提炼或迁移；具体例句与原文形式可能不同。","para":"I","examples":[{"en":"This was soon a resounding success, attracting thousands of tourists every year.","zh":"这一项目很快大获成功，每年吸引数千名游客。","source":"original","number":33,"paragraph":"I"}],"sourceId":"move-I4","paragraph":"I","origin":"原文词汇","contextLabel":"本文义","originalBinding":{"sentenceId":"move-I4","form":"a resounding success","kind":"literal"},"sourceOrder":330014},{"id":"move-532509f95b4d","term":"open up opportunities","type":"phrase","ipa":"","pos":"短语／搭配","stars":3,"zh":"创造机会","contextSenses":[0],"note":"原文是 opened up a world of options；opportunities 是近义改写，原句用 options。\n来源：词汇拓展或同义改写。未在原文中找到该表达，不附原文例句。\nfor后接受益者；正式表达可用 new opportunities。 由原句提炼或迁移；具体例句与原文形式可能不同。","para":"L","examples":[],"sourceId":null,"paragraph":null,"origin":"拓展词汇","contextLabel":"拓展释义","sourceOrder":10000084}],"sentences":[{"id":"move-A1","sourceId":"A1","en":"Like a passenger train, a roller coaster consists of a series of connected cars that move on a track.","zh":"像客运列车一样，过山车由一系列相互连接、沿轨道运行的车厢组成。","para":"A","note":"核心句式：Like X, Y consists of Z that…；主干是 a roller coaster consists of a series of connected cars。that move on a track 修饰 cars，故 move 用复数。cars 在此为车厢，不是私家车。","paragraph":"A"},{"id":"move-A2","sourceId":"A2","en":"But unlike a passenger train, it has no engine or power source of its own.","zh":"但与客运列车不同，它没有自己的发动机或动力源。","para":"A","note":"of its own 表示“它自己具有的”，不能把 own 理解为另一个动词。","paragraph":"A"},{"id":"move-A3","sourceId":"A3","en":"For most of the ride, it is moved only by the forces of inertia and gravity.","zh":"在行程的大部分时间里，它只靠惯性和重力作用而运动。","para":"A","note":"主干 it is moved by… 为被动结构；only 限定动力来源。For most of the ride 限定时间，并非整段行程都无外部动力。","paragraph":"A"},{"id":"move-A4","sourceId":"A4","en":"The only exertion of energy occurs at the very beginning of the ride when the coaster train is pulled up the lift hill.","zh":"唯一的能量投入发生在行程最开始，也就是过山车列车被拉上提升坡的时候。","para":"A","note":"主干 The only exertion of energy occurs…；when 引导时间从句说明开始阶段，is pulled up 是被动。very 在 the very beginning 中强调“最初”，不是“非常开始”。","paragraph":"A"},{"id":"move-B1","sourceId":"B1","en":"The traditional lifting mechanism is a long length of chain running up the hill under the track.","zh":"传统的提升装置是一条很长的链条，沿着轨道下方一直延伸到坡顶。","para":"B","note":"running up… 是现在分词短语，修饰 chain。这里介绍链条的布置；不能只凭 running 译成有人跑上坡。","paragraph":"B"},{"id":"move-B2","sourceId":"B2","en":"The chain is fastened in a loop, which is wound around a gear at the top of the hill and another one at the bottom.","zh":"链条被固定成一个环，绕在坡顶的一个齿轮和坡底的另一个齿轮上。","para":"B","note":"主干 The chain is fastened in a loop；which 从句补充说明这个环绕着两个齿轮。another one 中 one 代替 gear。识别 wound 为 wind 的过去分词。","paragraph":"B"},{"id":"move-B3","sourceId":"B3","en":"The gear at the bottom of the hill is turned by a motor.","zh":"坡底的齿轮由一台电动机带动旋转。","para":"B","note":"is turned by a motor 的 by 表动作执行者，不是位置“旁边”。","paragraph":"B"},{"id":"move-B4","sourceId":"B4","en":"This turns the chain so that it continually moves up the hill like a long conveyor belt.","zh":"这使链条转动起来，从而像一条长长的传送带一样持续向坡顶移动。","para":"B","note":"This 指电动机带动底部齿轮转动这件事。so that 引出这里的结果；it 指 chain，不是 motor。","paragraph":"B"},{"id":"move-B5","sourceId":"B5","en":"The coaster cars grip onto the chain, which simply pulls them to the top.","zh":"过山车的车厢抓住链条，链条就把它们拉到顶部。","para":"B","note":"which 指 chain；them 指 coaster cars。定语从句中的施力者是链条，不是车厢自己往上跑。","paragraph":"B"},{"id":"move-B6","sourceId":"B6","en":"At the summit, the train is released and starts its descent.","zh":"到达最高点时，列车被释放，开始下降。","para":"B","note":"descent 为“下降”，与 ascent“上升”成对记忆。is released 与 starts 是并列谓语，一个被动，一个主动。","paragraph":"B"},{"id":"move-C1","sourceId":"C1","en":"The purpose of this initial ascent is to build up a sort of reservoir of potential energy, which simply means that as the coaster gets higher in the air, there is a greater distance gravity can pull it down.","zh":"最初这次上升的目的，是积累某种势能储备；简单说，就是过山车升得越高，重力能将它向下拉动的距离就越大。","para":"C","note":"重点拆解：① The purpose of this initial ascent is to build up… 主系表，目的用 to do 表达。② which simply means that… 解释前面的“势能储备”。③ that 后的内容：as the coaster gets higher…, there is a greater distance…。④ gravity can pull it down 修饰 distance，关系词在原句省略，可理解为 the distance through which gravity can pull it down。先抓“目的→势能→高度与下降距离”的意义链，不必逐词硬译。","paragraph":"C"},{"id":"move-D1","sourceId":"D1","en":"As the train starts coasting down the hill, this potential energy is converted into kinetic energy (energy of motion), and the train speeds up.","zh":"列车开始沿坡滑下时，这些势能转化为动能，也就是运动的能量，列车随之加速。","para":"D","note":"As 引导时间从句。主句有两个并列分句：energy is converted… 和 the train speeds up。speed up＝accelerate；不要把 energy of motion 当作另一种能量。","paragraph":"D"},{"id":"move-D2","sourceId":"D2","en":"At the bottom of the hill, this has reached its maximum, and this propels the train up the second hill, again building up the potential-energy level.","zh":"到坡底时，动能达到最大值，推动列车爬上第二个坡，再次提高势能水平。","para":"D","note":"两个 this 均承接上句的动能。again building up… 为分词短语，说明再次上升带来的结果。不能把“最大值”套到坡底的势能上。","paragraph":"D"},{"id":"move-E1","sourceId":"E1","en":"In this way, the course of the track is constantly converting energy from kinetic to potential and back again.","zh":"通过这种方式，轨道的路线不断使能量在动能与势能之间来回转换。","para":"E","note":"from kinetic to potential and back again 表示双向循环，不是一次性的单方向转换。","paragraph":"E"},{"id":"move-E2","sourceId":"E2","en":"This fluctuation in acceleration is what makes roller coasters so much fun.","zh":"这种加速度的波动，正是过山车如此有趣的原因。","para":"E","note":"核心句式：X is what makes Y + 形容词或名词。what 引导表语从句，意为“使……的东西或原因”；makes roller coasters so much fun 是“使过山车充满乐趣”。","paragraph":"E"},{"id":"move-E3","sourceId":"E3","en":"At its most basic level, this is all a roller coaster is – a machine that uses gravity and inertia to send a train along a winding track.","zh":"从最基本的层面看，过山车就是这样一种机器：利用重力和惯性，让列车沿着弯曲的轨道行进。","para":"E","note":"this is all a roller coaster is 中 all 后省略 that，意为“过山车本质上就是这些”。破折号后 a machine… 为解释；that uses… 修饰 machine。句型 use A to do B 可以直接迁移到流程写作。","paragraph":"E"},{"id":"move-F1","sourceId":"F1","en":"Roller coasters have a long, fascinating history.","zh":"过山车有一段悠久而引人入胜的历史。","para":"F","note":"have a long history 可用于口语介绍地方或传统。","paragraph":"F"},{"id":"move-F2","sourceId":"F2","en":"Their direct ancestors were ice slides, popular in Russia in the 16th and 17th centuries.","zh":"它们的直接前身是冰滑道，十六和十七世纪时在俄国很流行。","para":"F","note":"popular in Russia… 是补充形容词短语，说明 ice slides。Their 指 roller coasters。","paragraph":"F"},{"id":"move-F3","sourceId":"F3","en":"They consisted of a long, steep, wooden slide covered in ice.","zh":"这些滑道由一条长而陡的木制滑道构成，表面覆盖着冰。","para":"F","note":"covered in ice 修饰 wooden slide，等于 which was covered in ice，是被动意义。","paragraph":"F"},{"id":"move-F4","sourceId":"F4","en":"Riders walked up a ladder or set of stairs to the top of the slide, as high as 21 metres up.","zh":"乘客沿着梯子或一段楼梯走到滑道顶端，最高可达离地二十一米。","para":"F","note":"a set of stairs 是一段或一组楼梯；as high as 21 metres up 补充高度，而不是说梯子只有一种固定高度。","paragraph":"F"},{"id":"move-F5","sourceId":"F5","en":"At the top, they climbed into sleds made of wood or blocks of ice and shot down the slope.","zh":"在顶端，他们坐进用木头或冰块做的雪橇，然后沿坡飞快地滑下。","para":"F","note":"made of wood or blocks of ice 修饰 sleds。climbed 与 shot 为并列谓语，主语均是 they。","paragraph":"F"},{"id":"move-F6","sourceId":"F6","en":"At the base, the sleds would crash-land in a sand pile.","zh":"到达底部时，雪橇会猛地落入一堆沙子中。","para":"F","note":"would 在历史叙述中表示过去经常发生的动作，不是对未来的猜测。","paragraph":"F"},{"id":"move-G1","sourceId":"G1","en":"It seems that the idea was then imported into France.","zh":"这一构想似乎随后传入了法国。","para":"G","note":"It seems that… 中 it 为形式主语；保留“似乎”，不要译成绝对事实。","paragraph":"G"},{"id":"move-G2","sourceId":"G2","en":"For most of the year, the warmer climate would melt the ice, so the French started building waxed slides instead.","zh":"一年中的大部分时间，较暖的气候会让冰融化，因此法国人转而建造涂蜡的滑道。","para":"G","note":"so 连接原因与结果；waxed slides 为涂蜡滑道，waxed 表被涂蜡，不是蜡做成的滑道。","paragraph":"G"},{"id":"move-G3","sourceId":"G3","en":"To help the sleds move down these slides, they added wheels, and in 1817, for the first time, a train was attached to the track.","zh":"为了帮助雪橇沿这些滑道滑下，他们给雪橇加上车轮；到一八一七年，列车首次被连接到轨道上。","para":"G","note":"To help… 是目的状语；help the sleds move 的 move 用原形。后半句 train was attached 被动，首次的年份是1817。","paragraph":"G"},{"id":"move-G4","sourceId":"G4","en":"The French continued to expand on this idea, coming up with more complex track layouts, with multiple cars and all sorts of twists and turns.","zh":"法国人继续发展这一构想，设计出更复杂的轨道布局，包括多节车厢和各种弯道转折。","para":"G","note":"coming up with… 为现在分词短语，说明发展构想的具体方式；with multiple cars… 描述新布局的特点。","paragraph":"G"},{"id":"move-H1","sourceId":"H1","en":"The first American roller coaster was built in the mountains of Pennsylvania in the mid-1800s, originally to provide an easy way to send coal to the railway 29 km down the mountain.","zh":"美国第一座过山车于十九世纪中叶建在宾夕法尼亚州山区，最初是为了方便把煤送到山下二十九公里处的铁路。","para":"H","note":"句子主干 The first American roller coaster was built…；originally to provide… 表最初目的；29 km down the mountain 修饰铁路的位置，不能改成坡高29公里。","paragraph":"H"},{"id":"move-H2","sourceId":"H2","en":"When the track was first built, a crew at the bottom of the mountain would attach the cart to a team of mules after emptying the load, and the mules would drag it back up to the top.","zh":"轨道刚建成时，山脚的工作人员会在卸空载荷后，把车连接到一队骡子上，由骡子把车拉回山顶。","para":"H","note":"When 引导时间从句；after emptying the load 的省略主语是 crew。主句 attach 与后一个分句 drag 串联运作过程；it 指 cart；would 表过去惯常动作。","paragraph":"H"},{"id":"move-H3","sourceId":"H3","en":"They were eventually replaced with steam engines to make the system more efficient.","zh":"后来，骡子最终被蒸汽机取代，使系统更加高效。","para":"H","note":"They 指上一句的 mules。to make… 是目的；make the system more efficient 为宾语加形容词补语。","paragraph":"H"},{"id":"move-I1","sourceId":"I1","en":"Soon after these improvements were made, the railway company built a new tunnel that brought the freight trains much closer to the coal mine.","zh":"这些改进完成后不久，铁路公司建了一条新隧道，使货运列车能到达离煤矿近得多的地方。","para":"I","note":"that brought… 修饰 tunnel；much 修饰比较级 closer。brought the trains closer 表示交通线路让列车更靠近煤矿。","paragraph":"I"},{"id":"move-I2","sourceId":"I2","en":"No longer required for its original purpose, the roller coaster was configured as a ‘scenic tour’.","zh":"由于原来的用途已不再需要，过山车被改设成一项观光游览。","para":"I","note":"No longer required… 是过去分词短语，补充原因，其逻辑主语是 the roller coaster。还原为 Because it was no longer required for its original purpose…。","paragraph":"I"},{"id":"move-I3","sourceId":"I3","en":"For one dollar, tourists got a leisurely ride up to the top of the mountain, followed by a wild, bumpy ride straight down.","zh":"游客花一美元，便可先悠闲地乘车上山，然后一路猛冲而下，体验颠簸刺激的旅程。","para":"I","note":"followed by… 表先后顺序，修饰前述上山行程。wild 在这里为刺激、猛烈，不是野生。","paragraph":"I"},{"id":"move-I4","sourceId":"I4","en":"This was soon a resounding success, attracting thousands of tourists every year.","zh":"这一项目很快大获成功，每年吸引数千名游客。","para":"I","note":"This 指改造后的观光项目；attracting… 是分词短语，补充成功的表现。","paragraph":"I"},{"id":"move-J1","sourceId":"J1","en":"Scenic rides like this continued to thrive and were joined by wooden roller coasters similar to the ones we know today.","zh":"类似的观光乘行项目继续蓬勃发展，并出现了与今天我们熟悉的过山车相似的木制过山车。","para":"J","note":"主语 Scenic rides 带两个谓语 continued 和 were joined。similar to… 修饰 wooden roller coasters；the ones 代替 roller coasters。","paragraph":"J"},{"id":"move-J2","sourceId":"J2","en":"These coasters were the main attraction at popular amusement parks throughout the United States, such as the many parks of Coney Island in New York.","zh":"这些过山车成为美国各地热门游乐园的主要吸引项目，例如纽约康尼岛的众多游乐园。","para":"J","note":"such as 引出例子；不要把康尼岛的公园理解为全美全部公园。","paragraph":"J"},{"id":"move-J3","sourceId":"J3","en":"By the 1920s, roller coasters were in full swing, with some 2,000 rides in operation around the country.","zh":"到二十世纪二十年代，过山车已进入全盛时期，全国约有两千个项目在运营。","para":"J","note":"By the 1920s 给出发展截止阶段；with some 2,000 rides in operation 为补充状态，rides 此处是游乐项目。","paragraph":"J"},{"id":"move-K1","sourceId":"K1","en":"Following the Great Depression, a decline in roller-coaster production began in the early 1930s, but a second roller-coaster boom in the 1970s and the beginning of the 1980s revitalised the amusement-park industry and introduced a slew of innovative tubular steel coasters.","zh":"大萧条之后，过山车生产从二十世纪三十年代初开始下滑；但七十年代及八十年代初的第二次繁荣，重振了游乐园行业，并带来了一大批创新的钢管过山车。","para":"K","note":"重点拆解：Following… 是时间背景；主句一 a decline… began…；but 后主句二 a second… boom revitalised… and introduced…。两个后置年代都修饰 boom。抓住“衰退 but 复苏”，再看两个复苏结果。tubular steel 指钢管结构。","paragraph":"K"},{"id":"move-L1","sourceId":"L1","en":"This was followed by a decline in interest for the rest of the decade, but since the early 1990s the amusement-park industry has experienced another coaster boom of sorts.","zh":"此后，这个十年余下的时期里，人们的兴趣下降了；但自二十世纪九十年代初以来，游乐园行业又经历了一轮某种程度上的过山车热潮。","para":"L","note":"This was followed by… 接续K段繁荣；the decade 指八十年代。since… has experienced 为现在完成时，连接过去起点与叙述当下。","paragraph":"L"},{"id":"move-L2","sourceId":"L2","en":"New launching techniques and other technological developments have opened up a world of options for designers, so in some rides you feel as if you are flying.","zh":"新的发射技术和其他技术发展为设计师带来了丰富的选择，因此在某些项目中，你会感觉仿佛在飞翔。","para":"L","note":"a world of options 是大量选择的比喻。so 引出结果，some rides 限定适用范围，不能扩大为所有项目。","paragraph":"L"},{"id":"move-L3","sourceId":"L3","en":"In the next few years we can expect to see many faster, taller and more twisted rides popping up in amusement parks around the world.","zh":"未来几年，我们可以预期在世界各地的游乐园里，出现许多更快、更高、弯曲程度更大的过山车。","para":"L","note":"expect to see + 宾语 + doing：see many… rides popping up。三个比较级并列；这是原文的展望，不要当成已发生的事实。","paragraph":"L"}],"examples":[],"questions":[],"references":[]};
